20	DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
21	                       const std::vector<std::string>& andes_supported) {
22	  DiffReport r;
23	
24	  cmp(r, "magic", ref.magic, got.magic);
25	  cmp(r, "version", ref.version, got.version);
26	  cmp(r, "flags", ref.flags, got.flags);
27	  cmp(r, "hart_id", ref.hart_id, got.hart_id);
28	  cmp(r, "priv", ref.priv, got.priv);
29	  cmp(r, "pc", ref.pc, got.pc);
30	
31	  // mepc/mcause: in the trap-free hybrid ROI they round-trip (L24: restored at
32	  // resume, re-read at drain). mtval/mstatus stay out of scope where they are
33	  // implementation-defined / carry dirty bits (false positives).
34	  cmp(r, "mepc", ref.mepc, got.mepc);
35	  cmp(r, "mcause", ref.mcause, got.mcause);
36	
37	  // Round-trip M-mode CSRs: mscratch (L23) and mtval/mie (L24) are restored at
38	  // resume and re-read at drain, so a trap-free ROI must match the oracle on
39	  // them. mip is excluded: its pending bits are hardware/platform-driven
40	  // (timer/external) and diverge between QEMU's functional clock and vsim's
41	  // cycle clock even with no trap (it still round-trips into the drained
42	  // record, just not the verifier).
43	  cmp(r, "mscratch", ref.mscratch, got.mscratch);
44	  cmp(r, "mtval", ref.mtval, got.mtval);
45	  cmp(r, "mie", ref.mie, got.mie);
46	
47	  for (int i = 0; i < 32; ++i)
48	    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);
49	
50	  if (ref.flags & HYBRID_FLAG_FP) {
51	    for (int i = 0; i < 32; ++i)
52	      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
53	    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
54	  }
